146	void WriteBufferFromS3::allocateBuffer()
147	{
148	    if (total_parts_uploaded != 0 && total_parts_uploaded % s3_settings.upload_part_size_multiply_parts_count_threshold == 0)
149	        upload_part_size *= s3_settings.upload_part_size_multiply_factor;
150	
151	    temporary_buffer = Aws::MakeShared<Aws::StringStream>("temporary buffer");
152	    temporary_buffer->exceptions(std::ios::badbit);
153	    last_part_size = 0;
154	}
