181	void WriteBufferFromS3::preFinalize()
182	{
183	    next();
184	
185	    if (multipart_upload_id.empty())
186	    {
187	        makeSinglepartUpload();
188	    }
189	    else
190	    {
191	        /// Write rest of the data as last part.
192	        writePart();
193	    }
194	
195	    is_prefinalized = true;
196	}
