198	void WriteBufferFromS3::finalizeImpl()
199	{
200	    if (!is_prefinalized)
201	        preFinalize();
202	
203	    waitForAllBackGroundTasks();
204	
205	    if (!multipart_upload_id.empty())
206	        completeMultipartUpload();
