209	void WriteBufferFromS3::createMultipartUpload()
210	{
211	    Aws::S3::Model::CreateMultipartUploadRequest req;
212	    req.SetBucket(bucket);
213	    req.SetKey(key);
214	
215	    /// If we don't do it, AWS SDK can mistakenly set it to application/xml, see https://github.com/aws/aws-sdk-cpp/issues/1840
216	    req.SetContentType("binary/octet-stream");
217	
218	    if (object_metadata.has_value())
219	        req.SetMetadata(object_metadata.value());
220	
221	    auto outcome = client_ptr->CreateMultipartUpload(req);
222	
223	    if (outcome.IsSuccess())
224	    {
225	        multipart_upload_id = outcome.GetResult().GetUploadId();
226	        LOG_TRACE(log, "Multipart upload has created. Bucket: {}, Key: {}, Upload id: {}", bucket, key, multipart_upload_id);
227	    }
228	    else
229	        throw Exception(outcome.GetError().GetMessage(), ErrorCodes::S3_ERROR);
230	}
