322	void WriteBufferFromS3::fillUploadRequest(Aws::S3::Model::UploadPartRequest & req, int part_number)
323	{
324	    req.SetBucket(bucket);
325	    req.SetKey(key);
326	    req.SetPartNumber(part_number);
327	    req.SetUploadId(multipart_upload_id);
328	    req.SetContentLength(temporary_buffer->tellp());
329	    req.SetBody(temporary_buffer);
330	
331	    /// If we don't do it, AWS SDK can mistakenly set it to application/xml, see https://github.com/aws/aws-sdk-cpp/issues/1840
332	    req.SetContentType("binary/octet-stream");
333	}
