335	void WriteBufferFromS3::processUploadRequest(UploadPartTask & task)
336	{
337	    auto outcome = client_ptr->UploadPart(task.req);
338	
339	    if (outcome.IsSuccess())
340	    {
341	        task.tag = outcome.GetResult().GetETag();
342	        LOG_TRACE(log, "Writing part finished. Bucket: {}, Key: {}, Upload_id: {}, Etag: {}, Parts: {}", bucket, key, multipart_upload_id, task.tag, part_tags.size());
343	    }
344	    else
345	        throw Exception(outcome.GetError().GetMessage(), ErrorCodes::S3_ERROR);
346	
347	    total_parts_uploaded++;
348	}
