350	void WriteBufferFromS3::completeMultipartUpload()
351	{
352	    LOG_TRACE(log, "Completing multipart upload. Bucket: {}, Key: {}, Upload_id: {}, Parts: {}", bucket, key, multipart_upload_id, part_tags.size());
353	
354	    if (part_tags.empty())
355	        throw Exception("Failed to complete multipart upload. No parts have uploaded", ErrorCodes::S3_ERROR);
356	
357	    Aws::S3::Model::CompleteMultipartUploadRequest req;
358	    req.SetBucket(bucket);
359	    req.SetKey(key);
360	    req.SetUploadId(multipart_upload_id);
361	
362	    Aws::S3::Model::CompletedMultipartUpload multipart_upload;
363	    for (size_t i = 0; i < part_tags.size(); ++i)
364	    {
365	        Aws::S3::Model::CompletedPart part;
366	        multipart_upload.AddParts(part.WithETag(part_tags[i]).WithPartNumber(i + 1));
367	    }
368	
369	    req.SetMultipartUpload(multipart_upload);
370	
371	    auto outcome = client_ptr->CompleteMultipartUpload(req);
372	
373	    if (outcome.IsSuccess())
374	        LOG_TRACE(log, "Multipart upload has completed. Bucket: {}, Key: {}, Upload_id: {}, Parts: {}", bucket, key, multipart_upload_id, part_tags.size());
375	    else
376	    {
377	        throw Exception(ErrorCodes::S3_ERROR, "{} Tags:{}",
378	            outcome.GetError().GetMessage(),
379	            fmt::join(part_tags.begin(), part_tags.end(), " "));
380	    }
381	}
