465	void WriteBufferFromS3::processPutRequest(PutObjectTask & task)
466	{
467	    auto outcome = client_ptr->PutObject(task.req);
468	    bool with_pool = static_cast<bool>(schedule);
469	    if (outcome.IsSuccess())
470	        LOG_TRACE(log, "Single part upload has completed. Bucket: {}, Key: {}, Object size: {}, WithPool: {}", bucket, key, task.req.GetContentLength(), with_pool);
471	    else
472	        throw Exception(outcome.GetError().GetMessage(), ErrorCodes::S3_ERROR);
473	}
