497	void WriteBufferFromS3::waitForReadyBackGroundTasks()
498	{
499	    if (schedule)
500	    {
501	        std::lock_guard lock(bg_tasks_mutex);
502	        {
503	            while (!upload_object_tasks.empty() && upload_object_tasks.front().is_finised)
504	            {
505	                auto & task = upload_object_tasks.front();
506	                auto exception = task.exception;
507	                auto tag = std::move(task.tag);
508	                upload_object_tasks.pop_front();
509	
510	                if (exception)
511	                {
512	                    waitForAllBackGroundTasks();
513	                    std::rethrow_exception(exception);
514	                }
515	
516	                part_tags.push_back(tag);
517	            }
518	        }
519	    }
520	}
521	
522	void WriteBufferFromS3::waitForAllBackGroundTasks()
523	{
524	    if (schedule)
525	    {
526	        std::unique_lock lock(bg_tasks_mutex);
527	        bg_tasks_condvar.wait(lock, [this]() { return num_added_bg_tasks == num_finished_bg_tasks; });
528	
529	        while (!upload_object_tasks.empty())
530	        {
531	            auto & task = upload_object_tasks.front();
532	            if (task.exception)
533	                std::rethrow_exception(task.exception);
534	
535	            part_tags.push_back(task.tag);
536	
537	            upload_object_tasks.pop_front();
538	        }
539	
540	        if (put_object_task)
541	        {
542	            bg_tasks_condvar.wait(lock, [this]() { return put_object_task->is_finised; });
543	            if (put_object_task->exception)
544	                std::rethrow_exception(put_object_task->exception);
545	        }
546	    }
547	}
