 41	/**
 42	 * Buffer to write a data to a S3 object with specified bucket and key.
 43	 * If data size written to the buffer is less than 'max_single_part_upload_size' write is performed using singlepart upload.
 44	 * In another case multipart upload is used:
 45	 * Data is divided on chunks with size greater than 'minimum_upload_part_size'. Last chunk can be less than this threshold.
 46	 * Each chunk is written as a part to S3.
 47	 */
 48	class WriteBufferFromS3 final : public BufferWithOwnMemory<WriteBuffer>
 49	{
 50	public:
 51	    WriteBufferFromS3(
 52	        std::shared_ptr<const Aws::S3::S3Client> client_ptr_,
 53	        const String & bucket_,
 54	        const String & key_,
 55	        const S3Settings::ReadWriteSettings & s3_settings_,
 56	        std::optional<std::map<String, String>> object_metadata_ = std::nullopt,
 57	        size_t buffer_size_ = DBMS_DEFAULT_BUFFER_SIZE,
 58	        ScheduleFunc schedule_ = {},
 59	        const WriteSettings & write_settings_ = {},
 60	        FileCachePtr cache_ = nullptr);
 61	
 62	    ~WriteBufferFromS3() override;
 63	
 64	    void nextImpl() override;
 65	
 66	    void preFinalize() override;
 67	
 68	private:
 69	    void allocateBuffer();
 70	
 71	    void createMultipartUpload();
 72	    void writePart();
 73	    void completeMultipartUpload();
 74	
 75	    void makeSinglepartUpload();
 76	
 77	    /// Receives response from the server after sending all data.
 78	    void finalizeImpl() override;
 79	
 80	    struct UploadPartTask;
 81	    void fillUploadRequest(Aws::S3::Model::UploadPartRequest & req, int part_number);
 82	    void processUploadRequest(UploadPartTask & task);
 83	
 84	    struct PutObjectTask;
 85	    void fillPutRequest(Aws::S3::Model::PutObjectRequest & req);
 86	    void processPutRequest(PutObjectTask & task);
 87	
 88	    void waitForReadyBackGroundTasks();
 89	    void waitForAllBackGroundTasks();
 90	
 91	    bool cacheEnabled() const;
 92	
 93	    String bucket;
 94	    String key;
 95	    std::shared_ptr<const Aws::S3::S3Client> client_ptr;
 96	    size_t upload_part_size = 0;
 97	    S3Settings::ReadWriteSettings s3_settings;
 98	    std::optional<std::map<String, String>> object_metadata;
 99	
100	    /// Buffer to accumulate data.
101	    std::shared_ptr<Aws::StringStream> temporary_buffer;
102	    size_t last_part_size = 0;
103	    std::atomic<size_t> total_parts_uploaded = 0;
104	
105	    /// Upload in S3 is made in parts.
106	    /// We initiate upload, then upload each part and get ETag as a response, and then finalizeImpl() upload with listing all our parts.
107	    String multipart_upload_id;
108	    std::vector<String> part_tags;
109	
110	    bool is_prefinalized = false;
111	
112	    /// Following fields are for background uploads in thread pool (if specified).
113	    /// We use std::function to avoid dependency of Interpreters
114	    ScheduleFunc schedule;
115	    std::unique_ptr<PutObjectTask> put_object_task;
116	    std::list<UploadPartTask> upload_object_tasks;
117	    size_t num_added_bg_tasks = 0;
118	    size_t num_finished_bg_tasks = 0;
119	    std::mutex bg_tasks_mutex;
120	    std::condition_variable bg_tasks_condvar;
121	
122	    Poco::Logger * log = &Poco::Logger::get("WriteBufferFromS3");
123	
124	    WriteSettings write_settings;
